// Polyfill for Node.js
const trace = typeof console !== 'undefined' ? console.log : () => {};

// Simulate pattern matching with functions

function processOption(option) {
    if (option && option.type === 'Some') {
        return "Got value: " + option.value;
    } else {
        return "No value";
    }
}

function categorizeNumber(n) {
    if (n < 0) return "Negative";
    else if (n === 0) return "Zero";
    else if (n <= 10) return "Small positive";
    else return "Large positive";
}

function processResult(result) {
    if (result.success) {
        return "Success: " + result.data;
    } else {
        return "Error: " + result.error;
    }
}

// Demo
trace("=== Pattern Matching Demo ===");
trace("");

trace("Option type:");
trace(processOption({ type: 'Some', value: 42 }));
trace(processOption({ type: 'None' }));
trace("");

trace("Number categorization:");
trace(categorizeNumber(-5) + " (-5)");
trace(categorizeNumber(0) + " (0)");
trace(categorizeNumber(7) + " (7)");
trace(categorizeNumber(100) + " (100)");
trace("");

trace("Result processing:");
trace(processResult({ success: true, data: "All good!" }));
trace(processResult({ success: false, error: "Something failed" }));
